import{_ as i,a0 as p,w as u,s as a,ao as l,I as n,x as o,a1 as s,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"一項研究顯示，谷歌在開源貢獻方面超過了微軟 | LCTT x X-CMD","titleTemplate":false,"description":"一項研究顯示，谷歌在開源貢獻方面超過了微軟 | LCTT (202208) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一項研究顯示，谷歌在開源貢獻方面超過了微軟 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一項研究顯示，谷歌在開源貢獻方面超過了微軟 | LCTT (202208) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202208/20220818 Google Surpasses Microsoft In Terms Of Open Source Contributors, Says A Study","title":"一項研究顯示，谷歌在開源貢獻方面超過了微軟","tag":"202208","desc":""},"relativePath":"202208/20220818 Google Surpasses Microsoft In Terms Of Open Source Contributors, Says A Study.md","filePath":"[post].md"}'),f={name:"202208/20220818 Google Surpasses Microsoft In Terms Of Open Source Contributors, Says A Study.md"};function d(m,t,T,S,C,g){const e=p("Link");return u(),a("div",null,[t[15]||(t[15]=l('<h1 id="一項研究顯示-谷歌在開源貢獻方面超過了微軟" tabindex="-1">一項研究顯示，谷歌在開源貢獻方面超過了微軟 <a class="header-anchor" href="#一項研究顯示-谷歌在開源貢獻方面超過了微軟" aria-label="Permalink to “一項研究顯示，谷歌在開源貢獻方面超過了微軟”">​</a></h1><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/08/coding-new-1536x864.jpg" alt=""></p><blockquote><p>根據 Aiven 的一份新報告，谷歌已經提高了其對開源軟件的投入，並在活躍貢獻者方面超過了微軟。</p></blockquote><p>根據 Aiven 的報告（LCTT 譯註：我沒有找到這份報告），谷歌目前的活躍貢獻者多於微軟，這要歸功於對開源代碼庫 GitHub 的每月提交量同比增長 20%。根據開源貢獻者指數（OCSI）的數據，谷歌 7 月份有 5421 名活躍貢獻者，而微軟的活躍貢獻者為 5268 名。</p><p>Aiven 聯合創始人兼首席技術官 Heikki Nousiainen 説，谷歌超過微軟“特別令人驚訝”。</p><p>“這其中的一個因素是微軟對開源項目的提交逐年下降，”Nousiainen 説，“然而，微軟對開發者自由和創新的投入是一致的，該公司是開源的主要參與者，甚至在 2018 年收購了 GitHub。”</p><p>Aiven 指出，亞馬遜已經開始更加重視開源計劃，其對 OpenSearch（ElasticSearch 的復刻）的支持以及 GitHub 上項目數量的增加就是證明。Nousiainen 認為，亞馬遜對 OpenSearch 和 ElasticSearch 的支持代表了“該公司方向的重大改變”，以及對重大開源項目掌舵的願望。據 Aiven 介紹，這些科技巨頭正在迅速擴大對開源軟件的使用。根據數據，現在來自亞馬遜、微軟和谷歌的活躍 GitHub 貢獻者比六年前多了 300%。</p><p>“這項研究的總體信息是積極的，”Nousiainen 説，“在開源社區有大量的創新在繼續發生，其結果使我們所有人受益。數不清的人正在為其他人樹立一個榜樣。”</p><hr>',9)),n("p",null,[t[1]||(t[1]=o("via: ",-1)),s(e,{href:"https://www.opensourceforu.com/2022/08/google-surpasses-microsoft-in-terms-of-open-source-contributors-says-a-study/"},{default:r(()=>[...t[0]||(t[0]=[o("https://www.opensourceforu.com/2022/08/google-surpasses-microsoft-in-terms-of-open-source-contributors-says-a-study/",-1)])]),_:1})]),n("p",null,[t[6]||(t[6]=o("作者：",-1)),s(e,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:r(()=>[...t[2]||(t[2]=[o("Laveesh Kocher",-1)])]),_:1}),t[7]||(t[7]=o(" 選題：",-1)),s(e,{href:"https://github.com/lkxed"},{default:r(()=>[...t[3]||(t[3]=[o("lkxed",-1)])]),_:1}),t[8]||(t[8]=o(" 譯者：",-1)),s(e,{href:"https://github.com/wxy"},{default:r(()=>[...t[4]||(t[4]=[o("wxy",-1)])]),_:1}),t[9]||(t[9]=o(" 校對：",-1)),s(e,{href:"https://github.com/wxy"},{default:r(()=>[...t[5]||(t[5]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[12]||(t[12]=o("本文由 ",-1)),s(e,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[10]||(t[10]=[o("LCTT",-1)])]),_:1}),t[13]||(t[13]=o(" 原創編譯，",-1)),s(e,{href:"https://linux.cn/"},{default:r(()=>[...t[11]||(t[11]=[o("Linux中國",-1)])]),_:1}),t[14]||(t[14]=o(" 榮譽推出",-1))])])}const y=i(f,[["render",d]]);export{b as __pageData,y as default};
